SELECT 'датчик схемы ' || fact_gap($1, 'sqlx-offline') || ': ответ неизвестен, а не «схема снята»' AS detail WHERE NOT fact_fresh($1, 'sqlx-offline') UNION ALL SELECT 'схема в .sqlx не снята: запросов 0, а в базу ходят '   || (SELECT count(*) FROM code_fact t WHERE t.project_id = $1 AND t.kind = 'db-test-file')   || ' файлов — офлайн-сборка невозможна, и ни одна интеграционная проверка не идёт' WHERE fact_fresh($1, 'sqlx-offline')   AND NOT EXISTS (SELECT 1 FROM code_fact c WHERE c.project_id = $1 AND c.kind = 'sqlx-offline')
